import{_ as e,o as d,c as t,a2 as c}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"导入节点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/import.md","filePath":"guide/import.md","lastUpdated":1794285179000}'),s={name:"guide/import.md"};function i(a,o,r,l,n,g){return d(),t("div",null,[...o[0]||(o[0]=[c('<h1 id="导入节点" tabindex="-1">导入节点 <a class="header-anchor" href="#导入节点" aria-label="Permalink to &quot;导入节点&quot;">​</a></h1><p>在 <strong>落地</strong> 页点击 <strong>导入</strong>，可以把不是面板部署的节点（脚本搭的、没装 agent 的机器、机场节点）加进来，用来对接中转和加入订阅。转换规则参考 Sub-Store：所有格式先转成 Mihomo（Clash Meta）节点格式保存，再按订阅格式输出，绝大多数参数会完整保留；少数只在 sing-box 原格式里有落点的字段没有对应搬运位置、转换时会丢弃，例如 Hysteria2 的 <code>up_mbps</code> / <code>down_mbps</code>、VLESS 的 <code>packet_encoding</code>。</p><h2 id="支持的输入" tabindex="-1">支持的输入 <a class="header-anchor" href="#支持的输入" aria-label="Permalink to &quot;支持的输入&quot;">​</a></h2><ul><li>分享链接（每行一个）：<code>ss://</code>（含 obfs / v2ray-plugin / shadow-tls 插件）、<code>vmess://</code>（v2rayN 格式）、<code>vless://</code>（含 Reality、WS、gRPC、H2、XHTTP）、<code>trojan://</code>、<code>hysteria2://</code> / <code>hy2://</code>、<code>tuic://</code>、<code>anytls://</code>、<code>socks5://</code> / <code>socks://</code>（同一协议的别名写法）、<code>naive://</code> / <code>naive+https://</code>（NaïveProxy，含面板自产的分享链接）</li><li>base64 订阅内容</li><li>Clash / Mihomo 配置（读取 <code>proxies</code>）</li><li>sing-box 配置（读取 <code>outbounds</code>）</li><li>Surge / Loon 节点行，例如 <code>名称 = snell, 1.2.3.4, 6160, psk=..., version=4</code></li><li>经 Clash / sing-box / Surge 形态还能导入 <strong>Snell</strong> 与 <strong>HTTP 代理</strong> 类型的节点——这两种没有可用的分享链接形态，只能走配置形态进来</li><li>文件上传：导入窗口里可以直接选文件，内容形态与上面粘贴的相同</li><li>订阅地址（<code>https://...</code>）：面板服务器以 <code>flmx-panel/1.0</code> 为 User-Agent 去下载（IMP-002：手册曾写&quot;以 Mihomo 的身份&quot;，与实际不符，已更正），拿到的通常是参数最完整的 Clash 配置。打开 <strong>定时同步</strong>（默认打开）会存成 <a href="./subscription#订阅源">订阅源</a>，按时更新；关掉则只导入一次。注意：依赖 UA 嗅探返回差异化内容的订阅源，可能返回参数不完整的内容</li><li>订阅源除 URL 外还可以建 <strong>file 型</strong>（把订阅内容存成文件源）：更新靠在订阅源列表里重新上传文件，后台不会自动拉取刷新</li></ul><h2 id="手动填写" tabindex="-1">手动填写 <a class="header-anchor" href="#手动填写" aria-label="Permalink to &quot;手动填写&quot;">​</a></h2><p>导入窗口顶部可以切到 <strong>手动填写</strong>：选好协议（SS / VLESS / VMess / Trojan / Hysteria2 / TUIC v5 / AnyTLS / SOCKS5），逐项填地址、端口、密码 / UUID，以及 TLS / Reality、传输方式（TCP / WebSocket / gRPC）等参数，UUID 可以点 <strong>生成</strong> 一键生成。点 <strong>添加</strong> 后，面板把填好的内容拼成标准分享链接，走与粘贴导入完全相同的解析与校验链路；添加后的节点和粘贴导入的节点一样，可以对接中转、放进订阅。Hysteria2 / TUIC / AnyTLS 作中转目标只能走 sing-box 内核，Xray 内核会拒绝。自检：点 <strong>添加</strong> 后，到入站列表确认节点出现，必要时用节点延迟测试验证连通——手动填写只有「已添加节点」提示、没有导入计数，填错地址／端口／凭据不会当场报错。</p><ul><li>表单只显示当前协议可用的字段与选项（例如 VMess 没有 Reality；Trojan / Hysteria2 / TUIC / AnyTLS 固定用 TLS）。流控（Vision）只在 VLESS + TCP 且安全不是「无」时可选；传输选 WebSocket / gRPC 或安全选「无」时选不出 Vision（已选的会被置空并提示），后端也会拒绝无 TLS 且无加密的 flow</li><li>地址栏只填域名或 IP，不要带端口（端口填在端口栏）；地址不能是本机地址（<code>127.0.0.1</code> 等）或保留段/组播段，带空标签的主机名（如 <code>a..b</code>）也会被拒绝；端口必须是 1–65535 的整数</li><li>按协议必填：VLESS / VMess / TUIC 须填 UUID；SS / Trojan / Hysteria2 / TUIC / AnyTLS 须填密码（TUIC 同时须填 UUID 和密码，是唯一同时要两样的协议）；VLESS + Reality 须填公钥（pbk）与 SNI（伪装站域名）；SOCKS5 的用户名和密码须成对填写（或都留空）；缺了会在点 <strong>添加</strong> 时直接提示，不会先建一个坏节点</li><li>名称可以留空，留空时用「地址:端口」作为节点名称</li></ul><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>暂不支持 WireGuard、SSR、Hysteria v1 等类型，导入时会逐条提示</li><li>Snell / NaïveProxy 作链式（中转）目标有内核版本门：经 sing-box 出站时 Snell 需要 sing-box 1.14 以上、NaïveProxy 需要 1.13 以上，低于门槛会在保存 / 下发时被点名拒绝（Hysteria2 / TUIC / AnyTLS 作中转目标只能走 sing-box、Xray 会拒绝，见「手动填写」）</li><li>Shadowsocks 类条目必须带密码：1.3.4 起，无密码（或加密方式为空）的 SS / SSU / TAP 配置在节点侧会<strong>直接报错、服务起不来</strong>，不再像旧版本那样静默以明文运行。导入或手工编写 gost 配置、手工链里有这类条目时，请先补上密码再下发；报错信息会明确指出缺 auth。面板正常创建的 SS 入站与 SS 链恒带密码，不受影响</li><li>节点地址不能是本机地址（<code>127.0.0.1</code> 等 loopback 地址或 <code>0.0.0.0</code>），导入时会被逐条拒绝并提示「地址不能是本机或 0.0.0.0」</li><li>保留段与组播段地址同样拒绝：云元数据地址、保留地址段（如 <code>0.x.x.x</code>）与组播地址（如 <code>224.0.0.0/4</code> 段）在导入与连通性检测时同样会被拒绝；公网、私网与运营商 NAT（CGNAT）地址不受影响</li><li>Shadowsocks 2022（<code>2022-blake3-*</code>）节点的密钥会校验格式：base64 解码后须为 16/32 字节，SIP023 冒号多段密钥按段逐段校验；不合规的单条节点会被拒绝并提示原因，其余节点照常导入。SIP023 多段合法节点在 sing-box 订阅中会逐段规范化为带填充的标准 base64 后下发（解码出的密钥字节不变；sing-box 1.11 / 1.12 / 1.14 均已实测可正常解析多段密钥）。此前已导入的异常节点（任一段密钥不合规）在<strong>所有</strong>订阅格式（sing-box、Clash、通用 base64、Loon、Quantumult X、Surge）渲染时都会被整节点略过、不再输出——面板不会为此单独提示，使用者在客户端里找不到该节点时多半是这个原因</li><li>Reality 链接参数（<code>pbk</code> / <code>sid</code> / <code>spx</code> / <code>realityDest</code>）都会解析保留：<code>realityDest</code> 须为 <code>host:port</code> 形式，坏值（缺端口、端口越界、空标签主机名如 <code>a..b:443</code>）整条拒绝，与创建入站同口径；<code>spx</code> 不能含空白或控制字符。合法值存入节点参数（入站详情的导入参数中可见 <code>reality-opts.dest</code> / <code>reality-opts.spider-x</code>），分享链接会原样回放，Xray 链式出站也会透传。sing-box 订阅格式没有对应的 <code>dest</code> / <code>spiderX</code> 字段，下发时不带这两项；Clash 家族（含 Stash、Shadowrocket 的 Clash 档案）则会把 <code>reality-opts</code> 整段透传输出，<code>dest</code> / <code>spider-x</code> 会随之带出（客户端一般会忽略这两个未知字段，不影响使用）。两种情况下值都仍保留在节点记录中，再导出分享链接时还在。VMess 链接（v2rayN JSON）同样支持 <code>tls=reality</code>：<code>sni</code> / <code>fp</code> / <code>alpn</code> / <code>pbk</code> / <code>sid</code> / <code>spx</code> / <code>realityDest</code> 都会解析保留，坏值（缺 <code>pbk</code>、坏 <code>realityDest</code>、缺 SNI 等）整条拒绝；<code>tls</code> 取值不在 <code>tls / reality / 留空（明文）</code> 内时整条拒绝，不会静默降级为明文；VLESS / Trojan 链接的 <code>security</code> 取未识别值时同样整条拒绝。</li><li>经中转连接时，原节点用域名连接的，会自动把域名保留为 TLS SNI 和 WebSocket Host；Hysteria2 端口跳跃只在直连线路上保留</li><li>面板不会部署、修改这些节点，也没有流量统计、白名单、换密钥等功能</li><li>原节点的地址或参数变了，点击该节点 → <strong>编辑</strong>，修改地址或粘贴新的链接替换参数，相关中转会自动指向新地址</li><li>勾选“订阅里只保留中转线路”后，订阅和分享中不再包含直连线路（该节点没有中转时就不会出现在订阅里）</li><li>删除只会删除面板里的记录和相关中转，不影响原服务器</li><li>导入去重按「地址＋端口＋协议＋凭据＋形态」判身份：五样全同才算重复，会被逐条点名拦下；同一个地址和端口只要协议、凭据或形态（传输方式／TLS 或 Reality／SNI 等）不同就可以并存，例如同一 host:端口、同一凭据的两条 VLESS，一条 WS＋Reality、一条 TCP＋TLS，是两个不同节点、都会导入，不是填错了（与面板自建入站同地址同端口不算重复，自建与导入可以共存）</li><li>单次导入上限 500 个节点（IMP-008）：<strong>手动导入</strong>（粘贴链接/内容）超过 500 个会直接拒绝，请分批导入；<strong>订阅源同步</strong>超过 500 个会只保留前 500 个，同步结果会显式标记截断状态并注明未同步的条数（手动刷新与后台自动同步口径一致）——两种口径不同是因为同步是周期性自动过程，整单拒绝会让该源的节点集一直停留在旧状态</li></ul><h2 id="连通性检测" tabindex="-1">连通性检测 <a class="header-anchor" href="#连通性检测" aria-label="Permalink to &quot;连通性检测&quot;">​</a></h2><p>面板服务器每 3 分钟会连一次所有导入的节点，落地页上方的 <strong>检测</strong> 按钮可以马上测一遍：</p><ul><li>连得上：绿点，后面显示延迟（例如 <code>· 85 ms</code>）</li><li>连不上：红点，并显示原因（连接超时、域名解析失败、无法连接）</li></ul><p>检测是从 <strong>面板服务器</strong> 发起的 TCP 连接，只能作为参考：面板连不上不代表中转机也连不上，反之亦然。Hysteria2、TUIC 只用 UDP，无法这样检测，不显示状态。开启 <a href="./notify">通知</a> 后，导入节点连续两次连不上会推送提醒。</p><h2 id="对接中转" tabindex="-1">对接中转 <a class="header-anchor" href="#对接中转" aria-label="Permalink to &quot;对接中转&quot;">​</a></h2><p>导入后的节点和面板部署的入站一样：点击节点 → <strong>中转</strong> → 选择隧道即可，端口转发和隧道转发（包括经 IX 的多跳）都可以用。Hysteria2 / TUIC / AnyTLS 作中转目标只能走 sing-box 内核，Xray 内核会拒绝。见 <a href="./relay">对接中转</a>。</p><h2 id="订阅源地址安全策略" tabindex="-1">订阅源地址安全策略 <a class="header-anchor" href="#订阅源地址安全策略" aria-label="Permalink to &quot;订阅源地址安全策略&quot;">​</a></h2><p>订阅源 URL 默认仅支持 <strong>https 公网地址</strong>。如需使用 http 或内网地址，需管理员显式配置：</p><ul><li><code>FLMX_FETCH_ALLOW_PRIVATE_NETWORKS=true</code>：放行所有私网地址（不推荐）</li><li><code>FLMX_FETCH_PRIVATE_ALLOWLIST=192.168.0.0/16,10.0.0.0/8</code>：仅放行指定 CIDR（推荐）</li></ul><p><strong>设置位置与生效方法</strong>：这两个变量是<strong>后端进程的环境变量</strong>。随版 <code>docker-compose.yml</code> 的 <code>backend</code> 服务 <code>environment:</code> 段默认<strong>没有</strong>它们的传递行——只把变量写进部署目录的 <code>.env</code> 文件<strong>不会生效</strong>（后端读的是进程环境，不是 <code>.env</code> 文件本身）。正确做法：在部署目录的 <code>docker-compose.yml</code> 里给 <code>backend</code> 服务补上对应传递行（写字面量，或写 <code>- FLMX_FETCH_PRIVATE_ALLOWLIST=${FLMX_FETCH_PRIVATE_ALLOWLIST}</code> 再把值放进同目录 <code>.env</code>），保存后执行 <code>docker compose up -d backend</code> 重建后端容器才生效。自检：<code>docker exec &lt;后端容器&gt; printenv FLMX_FETCH_PRIVATE_ALLOWLIST</code> 能打印出所设值，即已进入后端进程；打印为空就是传递行没补对。全部 <code>FLMX_FETCH_*</code> 变量均为同一口径。</p><p><strong>风险说明</strong>：放行私网地址会允许面板服务器访问内网资源。请确保订阅源可信，并注意：</p><ul><li>云元数据地址（<code>169.254.169.254</code>）在任何配置下都被拒绝</li><li>私网放行会记录审计日志</li><li>公网 http 在任何配置下都被拒绝（必须使用 https）</li></ul>',21)])])}const h=e(s,[["render",i]]);export{p as __pageData,h as default};
